#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 15
#define MAXM 105

int n, m;
double p;
int u[MAXM], v[MAXM];
double dp[1 << MAXN];

int main() {
    scanf("%d %d %lf", &n, &m, &p);
    for (int i = 0; i < m; i++) {
        scanf("%d %d", &u[i], &v[i]);
        u[i]--; v[i]--;
    }

    int full = (1 << n) - 1;

    // dp[mask] = probability that the subgraph induced by 'mask' is connected
    // We compute using inclusion-exclusion: 
    // For each subset, probability that it is connected = 
    // 1 - sum over proper non-empty subsets containing a fixed vertex of 
    // (probability that subset splits into that component and the rest) 

    for (int mask = 1; mask <= full; mask++) {
        if (mask == (mask & -mask)) { // single vertex
            dp[mask] = 1.0;
            continue;
        }

        // Count internal edges (both endpoints in mask)
        int internal_edges = 0;
        for (int i = 0; i < m; i++) {
            if ((mask >> u[i] & 1) && (mask >> v[i] & 1)) {
                internal_edges++;
            }
        }

        // Pick a fixed vertex (lowest set bit) to avoid overcounting
        int fixed = __builtin_ctz(mask);
        int rest = mask ^ (1 << fixed);

        // Iterate over proper subsets of rest that are non-empty
        double sum = 0.0;
        for (int sub = rest; sub; sub = (sub - 1) & rest) {
            int comp = sub | (1 << fixed);

            // Count edges between comp and mask\comp
            int cut_edges = 0;
            for (int i = 0; i < m; i++) {
                int a = u[i], b = v[i];
                if (((mask >> a & 1) && (mask >> b & 1)) &&
                    ((comp >> a & 1) != (comp >> b & 1))) {
                    cut_edges++;
                }
            }

            double prob_disconnect = dp[comp] * (1.0 - p);
            // Multiply by probability that all cut edges are missing
            for (int e = 0; e < cut_edges; e++) {
                prob_disconnect *= p;
            }
            sum += prob_disconnect;
        }

        dp[mask] = 1.0 - sum;
    }

    printf("%.10lf\n", dp[full]);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 55
#define MAXM 2005
#define EPS 1e-12

typedef struct {
    int u, v;
    double p;
} Edge;

static int n, m;
static Edge edges[MAXM];

static int parent_[MAXN];

static int find_set(int x) {
    if (parent_[x] == x) return x;
    parent_[x] = find_set(parent_[x]);
    return parent_[x];
}

static void union_set(int a, int b) {
    a = find_set(a);
    b = find_set(b);
    if (a != b) parent_[a] = b;
}

static double determinant(double a[MAXN][MAXN], int sz) {
    double det = 1.0;
    for (int i = 0; i < sz; i++) {
        int pivot = i;
        for (int j = i; j < sz; j++) {
            if (fabs(a[j][i]) > fabs(a[pivot][i])) pivot = j;
        }
        if (fabs(a[pivot][i]) < EPS) return 0.0;
        if (pivot != i) {
            for (int k = i; k < sz; k++) {
                double tmp = a[i][k];
                a[i][k] = a[pivot][k];
                a[pivot][k] = tmp;
            }
            det = -det;
        }
        det *= a[i][i];
        double div = a[i][i];
        for (int j = i + 1; j < sz; j++) {
            double factor = a[j][i] / div;
            if (fabs(factor) < EPS) continue;
            for (int k = i; k < sz; k++) {
                a[j][k] -= factor * a[i][k];
            }
        }
    }
    return det;
}

int main(void) {
    if (scanf("%d%d", &n, &m) != 2) return 0;

    double base = 1.0;

    for (int i = 1; i <= n; i++) parent_[i] = i;

    for (int i = 0; i < m; i++) {
        int u, v;
        double q;
        scanf("%d%d%lf", &u, &v, &q);
        edges[i].u = u;
        edges[i].v = v;
        edges[i].p = q; /* disappearance probability */

        if (q >= 1.0 - EPS) continue; /* always disappears */
        union_set(u, v);
        base *= (1.0 - q);
    }

    int root = find_set(1);
    for (int i = 2; i <= n; i++) {
        if (find_set(i) != root) {
            printf("0.000000\n");
            return 0;
        }
    }

    double lap[MAXN][MAXN];
    memset(lap, 0, sizeof(lap));

    for (int i = 0; i < m; i++) {
        double q = edges[i].p;
        if (q >= 1.0 - EPS) continue;
        double w = q / (1.0 - q);
        int u = edges[i].u - 1;
        int v = edges[i].v - 1;
        lap[u][u] += w;
        lap[v][v] += w;
        lap[u][v] -= w;
        lap[v][u] -= w;
    }

    if (n == 1) {
        printf("1.000000\n");
        return 0;
    }

    double mat[MAXN][MAXN];
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1; j++) {
            mat[i][j] = lap[i][j];
        }
    }

    double tree_sum = determinant(mat, n - 1);
    double ans = base * tree_sum;

    if (ans < 0 && ans > -1e-9) ans = 0;
    printf("%.6f\n", ans);
    return 0;
}

