int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    double p;
    cin >> n >> m >> p;

    vector<pair<int,int>> edges(m);
    for (int i = 0; i < m; i++) {
        cin >> edges[i].first >> edges[i].second;
        edges[i].first--;
        edges[i].second--;
    }

    int total_masks = 1 << n;
    vector<double> prob_connected(total_masks, 0.0);
    prob_connected[0] = 1.0; // empty set is trivially connected

    // Precompute edge count for each subset
    vector<int> edge_count(total_masks, 0);
    for (int mask = 0; mask < total_masks; mask++) {
        for (auto &e : edges) {
            int u = e.first, v = e.second;
            if ((mask >> u & 1) && (mask >> v & 1)) {
                edge_count[mask]++;
            }
        }
    }

    // DP over subsets
    for (int mask = 1; mask < total_masks; mask++) {
        // Find lowest set bit
        int lsb = mask & -mask;
        int v = __builtin_ctz(lsb); // vertex index of lsb

        // Iterate over proper non-empty submasks containing v
        int sub = (mask - 1) & mask;
        while (sub) {
            if (sub & lsb) {
                int other = mask ^ sub;
                // probability that all edges inside sub are present
                double prob_inside = pow(p, edge_count[sub]);
                // probability that no edges cross between sub and other
                int cross = 0;
                for (auto &e : edges) {
                    int u = e.first, w = e.second;
                    if (((sub >> u & 1) && (other >> w & 1)) ||
                        ((sub >> w & 1) && (other >> u & 1))) {
                        cross++;
                    }
                }
                double prob_no_cross = pow(1.0 - p, cross);
                prob_connected[mask] += prob_connected[sub] * prob_inside * prob_no_cross;
            }
            sub = (sub - 1) & mask;
        }
        // The formula gives probability that graph restricted to mask
        // is disconnected. So connected = 1 - disconnected.
        prob_connected[mask] = 1.0 - prob_connected[mask];
    }

    cout << fixed << setprecision(10) << prob_connected[total_masks - 1] << "\n";

    return 0;
}

