        vector<vector<int>> g(n);
        for (int i = 0; i < m; ++i) {
            if (mask & (1 << i)) {
                auto [u, v] = edges[i];
                g[u].push_back(v);
                g[v].push_back(u);
            }
        }

        vector<int> vis(n, 0);
