import java.util.*;

public class Main {
    static int n;
    static int[][] edges;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        int m = sc.nextInt();
        double p = sc.nextDouble();

        edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            edges[i][0] = sc.nextInt() - 1;
            edges[i][1] = sc.nextInt() - 1;
        }

        double survive = 1.0 - p;
        double ans = 0.0;

        for (int mask = 0; mask < (1 << m); mask++) {
            if (isConnected(mask, n, edges)) {
                int kept = Integer.bitCount(mask);
                int removed = m - kept;
                ans += Math.pow(survive, kept) * Math.pow(p, removed);
            }
        }

        System.out.printf("%.9f%n", ans);
    }

    static boolean isConnected(int mask, int n, int[][] edges) {
        // Union-Find
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        for (int i = 0; i < edges.length; i++) {
            if ((mask & (1 << i)) != 0) {
                union(parent, edges[i][0], edges[i][1]);
            }
        }

        int root = find(parent, 0);
        for (int i = 1; i < n; i++) {
            if (find(parent, i) != root) return false;
        }
        return true;
    }

    static int find(int[] parent, int x) {
        if (parent[x] != x) parent[x] = find(parent, parent[x]);
        return parent[x];
    }

    static void union(int[] parent, int a, int b) {
        parent[find(parent, a)] = find(parent, b);
    }
}

import java.io.*;
import java.util.*;

/*
We need the probability that an undirected graph remains connected after each edge
independently disappears with probability q (so survives with probability p = 1-q).

For a general graph this is the all-terminal reliability problem, which is #P-hard.
The intended solvable case is a small number of vertices. We use the standard subset DP:

Let f[S] = probability that the random subgraph induced by S is connected.
For any nonempty S and the smallest vertex r in S,

f[S] = 1 - sum over connected component T of r with T proper subset of S:
          f[T] * product_{u in T, v in S\T, uv in E}(1-p)

Rearranged in the usual recurrence:
g[S] = probability that the component containing r is exactly S within the graph on S_all
For fixed universe U,
g[T] = f[T] * noEdge(T, U\T)
and sum_{T containing r} g[T] = 1, hence
f[U] = 1 - sum_{proper T containing r} f[T] * noEdge(T, U\T)

We compute for all subsets by increasing size.

Input format is not explicitly given in the prompt, so we support a common format:
n m q
u1 v1
...
um vm

Vertices may be 1-indexed in input.

Output probability as double.

Complexity: O(3^n * n^2) via subset iteration, suitable for small n.
*/

public class Main {
    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        Integer nObj = fs.nextIntNullable();
        if (nObj == null) return;
        int n = nObj;
        int m = fs.nextInt();
        double q = fs.nextDouble();
        double p = 1.0 - q;

        boolean[][] adj = new boolean[n][n];
        for (int i = 0; i < m; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            if (u >= 1 && v >= 1 && (u > n || v > n)) {
                // nothing special, assume still 1-indexed impossible check not useful
            }
            // assume 1-indexed if in [1..n]
            if (u >= 1 && u <= n && v >= 1 && v <= n) {
                u--; v--;
            }
            if (u == v) continue;
            adj[u][v] = adj[v][u] = true;
        }

        int N = 1 << n;

        // cutProb[A][B] only needed as noEdge(A, complement within S), computed from edge counts.
        // Precompute for every subset mask and vertex v:
        // cnt[v][mask] = number of neighbors of v inside mask
        int[][] cnt = new int[n][N];
        for (int v = 0; v < n; v++) {
            for (int mask = 1; mask < N; mask++) {
                int b = mask & -mask;
                int u = Integer.numberOfTrailingZeros(b);
                cnt[v][mask] = cnt[v][mask ^ b] + (adj[v][u] ? 1 : 0);
            }
        }

        // edgesAcross[T][S\T] can be computed incrementally when needed from cnt.
        double[] f = new double[N];
        f[0] = 0.0;

        for (int mask = 1; mask < N; mask++) {
            int r = Integer.numberOfTrailingZeros(mask);
            double sum = 0.0;

            // iterate proper submasks containing r
            for (int sub = (mask - 1) & mask; sub > 0; sub = (sub - 1) & mask) {
                if (((sub >> r) & 1) == 0) continue;
                if (sub == mask) continue;

                int other = mask ^ sub;

                int crossEdges = 0;
                int x = sub;
                while (x != 0) {
                    int b = x & -x;
                    int v = Integer.numberOfTrailingZeros(b);
                    crossEdges += cnt[v][other];
                    x ^= b;
                }

                double noEdge = Math.pow(q, crossEdges);
                sum += f[sub] * noEdge;
            }

            f[mask] = 1.0 - sum;
            if (f[mask] < 0 && f[mask] > -1e-12) f[mask] = 0;
            if (f[mask] > 1 && f[mask] < 1 + 1e-12) f[mask] = 1;
        }

        System.out.printf(Locale.US, "%.10f%n", f[N - 1]);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }
}
